using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1. GetTypeInfo<T>() — returns JsonTypeInfo<T> directly, no cast needed
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

Person? deserialized = JsonSerializer.Deserialize(json, personInfo);
Console.WriteLine($"Deserialized: {deserialized}");

// 2. TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? resolvedInfo))
{
    Console.WriteLine($"\nTryGetTypeInfo<Person> succeeded — Type: {resolvedInfo!.Type.Name}");
}

// Now demonstrate a case where metadata is NOT available.
// Use a source-gen context that only knows about Person.
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyContext()
};

if (restrictedOptions.TryGetTypeInfo<Person>(out _))
{
    Console.WriteLine("\nRestrictedOptions: Person metadata IS available ✓");
}

if (restrictedOptions.TryGetTypeInfo<Order>(out _))
{
    Console.WriteLine("RestrictedOptions: Order metadata IS available");
}
else
{
    Console.WriteLine("RestrictedOptions: Order metadata is NOT available — no exception thrown ✓");
}

